<script setup>
import { uniqueKey } from '../../services/ids.js';
import { reactive,ref,computed,onMounted,onUnmounted } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace } from '../../services/workspace.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { fetchAll,idOf,money } from '../../services/panel.js';
import { CategoryTree } from '../../services/categories.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>!!route.params.id),loading=ref(true),saving=ref(false),uploading=ref(false),error=ref(''),categories=ref([]),products=ref([]),relatedSearch=ref('');
const form=reactive({name:'',description:'',categoryId:'',type:'physical',digitalUrl:'',images:[],price:0,previousPrice:0,active:true,featured:false,madeToOrder:false,stock:0,variants:[],relatedProductIds:[]});
const sessionUploads=new Set();
const related=computed(()=>products.value.filter(p=>p._id!==route.params.id&&p.name.toLowerCase().includes(relatedSearch.value.toLowerCase())));
const categoryTree=computed(()=>new CategoryTree(categories.value));
const categoryOptions=computed(()=>categoryTree.value.rows());

onMounted(async()=>{try{[categories.value,products.value]=await Promise.all([fetchAll(`/stores/${workspace.activeStoreId}/categories`),fetchAll(`/stores/${workspace.activeStoreId}/products`)]);if(editing.value){const p=await api.get(`/stores/${workspace.activeStoreId}/products/${route.params.id}`);Object.assign(form,p);form.categoryId=idOf(p.categoryId);form.relatedProductIds=p.relatedProductIds?.map(idOf)||[];form.variants=(p.variants||[]).map(v=>({...v,attributes:{talle:'',color:'',...(v.attributes||{})}}));}}catch(e){error.value=e.message}finally{loading.value=false}});
async function upload(e){const files=[...e.target.files];e.target.value='';if(!files.length)return;if(files.some(f=>f.size>5*1024*1024)){notify.error('Cada foto puede pesar hasta 5 MB.');return}if(form.images.length+files.length>5){notify.error('Podés agregar hasta 5 fotos por producto.');return}const data=new FormData();for(const f of files)data.append('files',f);uploading.value=true;try{const uploaded=await api.upload(`/stores/${workspace.activeStoreId}/uploads`,data);for(const item of uploaded){form.images.push(item.url);sessionUploads.add(item.url);}notify.success('Fotos cargadas en R2. Guardá el producto para conservar los cambios.')}catch(e){notify.error(e.message)}finally{uploading.value=false}}

async function cleanupUploads(urls=[...sessionUploads]){const storeId=workspace.activeStoreId,list=[...new Set(urls)].filter(Boolean);for(const url of list)sessionUploads.delete(url);if(!storeId||!list.length)return;try{await api.delete(`/stores/${storeId}/uploads`,{urls:list});}catch(e){console.warn('[r2-cleanup]',e.message);}}
async function removeImage(index){const url=form.images[index];form.images.splice(index,1);if(sessionUploads.has(url))await cleanupUploads([url]);}
onBeforeRouteLeave(async()=>{await cleanupUploads();return true;});
onUnmounted(()=>{cleanupUploads();});
function addVariant(){form.variants.push({id:uniqueKey(),name:'',sku:'',stock:0,price:'',attributes:{talle:'',color:''}})}
async function removeVariant(i){if(editing.value&&!await confirmDialog({title:'Quitar variante',message:'La variante dejará de estar disponible para nuevas compras. Si tiene pedidos reservados, no se podrá quitar hasta resolverlos.',confirmText:'Quitar variante'}))return;form.variants.splice(i,1)}
async function save(){saving.value=true;error.value='';try{const data={...form,categoryId:form.categoryId||null,variants:form.variants.map(v=>({...v,price:v.price===''||v.price==null?undefined:Number(v.price),attributes:Object.fromEntries(Object.entries(v.attributes||{}).filter(([,val])=>String(val).trim()))}))};const path=`/stores/${workspace.activeStoreId}/products`;if(editing.value)await api.put(`${path}/${route.params.id}`,data);else await api.post(path,data);notify.success(editing.value?'Producto actualizado.':'Producto creado.');await cleanupUploads();router.push('/app/products')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
function reorder(i,d){const target=i+d;if(target<0||target>=form.images.length)return;[form.images[i],form.images[target]]=[form.images[target],form.images[i]]}
</script>
<template><div><RouterLink to="/app/products" class="p-back-link"><Icon name="back" :size="14"/>Volver a productos</RouterLink><header class="p-page-header"><div><h1>{{editing?'Editá cada detalle':'Dale lugar a tu próximo favorito.'}}</h1><p>Fotos claras, una buena descripción y toda la información para comprar con confianza.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else @submit.prevent="save" class="p-form"><div class="p-two-column"><div><section class="p-section-card"><div class="p-section-title"><div><h2>Información del producto</h2><p>Contale a tus clientes qué lo hace especial.</p></div><Icon name="package"/></div><div class="p-form-grid"><div class="p-field full"><label for="product-name">Nombre *</label><input id="product-name" v-model.trim="form.name" required maxlength="160" placeholder="Por ejemplo: Cuaderno artesanal A5"/></div><div class="p-field full"><label for="product-description">Descripción</label><textarea id="product-description" v-model="form.description" maxlength="10000" rows="5" placeholder="Materiales, medidas, usos y todos los detalles importantes..."/></div><div class="p-field full"><label for="product-category">Categoría o subcategoría</label><select id="product-category" v-model="form.categoryId" aria-describedby="product-category-help"><option value="">Sin categoría</option><option v-for="c in categoryOptions" :key="c._id" :value="c._id">{{c.categoryPath}}{{!c.active?' (oculta)':''}}</option></select><small id="product-category-help">Elegí cualquier nivel. El producto también aparece al filtrar por sus categorías superiores.</small></div><div class="p-field"><label for="product-type">Tipo de producto *</label><select id="product-type" v-model="form.type"><option value="physical">Físico</option><option value="digital">Digital</option></select></div><div v-if="form.type==='digital'" class="p-field full"><label for="digital-url">Enlace de entrega digital *</label><input id="digital-url" v-model.trim="form.digitalUrl" required type="url" placeholder="https://..."/><small>Este enlace es privado. Se envía al correo del comprador después de confirmar el pago.</small></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Fotos que invitan a comprar</h2><p>Hasta 5 fotos. La primera es la portada del producto.</p></div><span class="p-badge">{{form.images.length}} / 5</span></div><label v-if="form.images.length<5" class="p-upload"><input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="upload" aria-label="Cargar fotos del producto"/><Icon :name="uploading?'clock':'upload'" :size="28"/><span><strong>{{uploading?'Subiendo tus fotos...':'Elegí fotos de tu dispositivo'}}</strong><small>JPG, PNG o WebP · hasta 5 MB por imagen</small></span></label><div class="p-images"><div v-for="(img,i) in form.images" :key="img+i"><div class="p-image-item"><img :src="img" :alt="`Foto ${i+1} del producto`"/><button type="button" @click="removeImage(i)" :aria-label="`Quitar foto ${i+1}`"><Icon name="close" :size="13"/></button><small>{{i===0?'Portada':`Foto ${i+1}`}}</small></div><div class="p-reorder-controls"><button type="button" class="p-icon-btn" :disabled="i===0" :aria-label="`Mover foto ${i+1} a la izquierda`" @click="reorder(i,-1)"><Icon name="back" :size="12"/></button><button type="button" class="p-icon-btn" :disabled="i===form.images.length-1" :aria-label="`Mover foto ${i+1} a la derecha`" @click="reorder(i,1)"><Icon name="arrow" :size="12"/></button></div></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Precio y disponibilidad</h2><p>Importes en pesos argentinos.</p></div></div><div class="p-form-grid"><div class="p-field"><label for="product-price">Precio de venta *</label><input id="product-price" v-model.number="form.price" type="number" min="0.01" step="0.01" required/></div><div class="p-field"><label for="product-previous">Precio anterior</label><input id="product-previous" v-model.number="form.previousPrice" type="number" min="0" step="0.01"/><small>Para mostrar una oferta. 0 lo oculta.</small></div><div v-if="form.type==='physical'" class="p-field full"><label class="p-check"><input v-model="form.madeToOrder" type="checkbox"/>Lo realizo a pedido, sin límite de stock</label><small>La compra genera un pedido de fabricación; no descuenta existencias.</small></div><div v-if="form.type==='physical'&&!form.madeToOrder&&!form.variants.length" class="p-field"><label for="product-stock">{{editing?'Stock disponible':'Stock inicial'}} *</label><input id="product-stock" v-model.number="form.stock" type="number" min="0" step="1" required :disabled="editing"/><small v-if="editing">Modificá las existencias desde <RouterLink to="/app/stock">Stock</RouterLink> para registrar cada ajuste.</small></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Variantes</h2><p>Ofrecé talles, colores o combinaciones. Cada variante puede tener su propio precio.</p></div><button type="button" class="btn btn-secondary btn-small" :disabled="form.variants.length>=100" @click="addVariant"><Icon name="plus" :size="13"/>Agregar variante</button></div><div v-if="editing&&form.variants.length" class="p-info">Los cambios de existencias se realizan en Stock. Las variantes nuevas comienzan en 0 hasta que les asignes stock.</div><div v-if="!form.variants.length" class="p-help">El producto se ofrecerá en una única presentación.</div><div v-for="(v,i) in form.variants" :key="v.id" class="p-nested-card"><header><strong>Variante {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar variante" @click="removeVariant(i)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field"><label :for="`variant-name-${i}`">Nombre *</label><input :id="`variant-name-${i}`" v-model.trim="v.name" required maxlength="100" placeholder="Por ejemplo: M · Negro"/></div><div class="p-field"><label :for="`variant-sku-${i}`">Código / SKU</label><input :id="`variant-sku-${i}`" v-model.trim="v.sku" maxlength="100"/></div><div class="p-field"><label :for="`variant-size-${i}`">Talle</label><input :id="`variant-size-${i}`" v-model.trim="v.attributes.talle" maxlength="100" placeholder="M"/></div><div class="p-field"><label :for="`variant-color-${i}`">Color</label><input :id="`variant-color-${i}`" v-model.trim="v.attributes.color" maxlength="100" placeholder="Negro"/></div><div class="p-field"><label :for="`variant-price-${i}`">Precio propio (opcional)</label><input :id="`variant-price-${i}`" v-model="v.price" type="number" min="0.01" step="0.01" :placeholder="String(form.price)"/><small>Vacío: usa el precio del producto.</small></div><div v-if="form.type==='physical'&&!form.madeToOrder" class="p-field"><label :for="`variant-stock-${i}`">{{editing?'Stock actual':'Stock inicial'}}</label><input :id="`variant-stock-${i}`" v-model.number="v.stock" :disabled="editing" type="number" min="0" step="1"/></div></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Productos relacionados</h2><p>Aparecerán debajo de la ficha del producto. Elegí todos los que combinen bien.</p></div><span class="p-badge">{{form.relatedProductIds.length}} seleccionados</span></div><div class="p-field" style="margin-bottom:14px"><input v-model="relatedSearch" type="search" placeholder="Buscar productos relacionados..." aria-label="Buscar productos relacionados"/></div><div class="p-select-list"><label v-for="p in related" :key="p._id" class="p-tag-option"><input v-model="form.relatedProductIds" :value="p._id" type="checkbox" :disabled="form.relatedProductIds.length>=50&&!form.relatedProductIds.includes(p._id)"/>{{p.name}}</label><p v-if="!related.length" class="p-help">{{products.length<=1?'Cuando agregues más productos podrás relacionarlos.':'No hay productos para esa búsqueda.'}}</p></div><div class="p-info">Las recomendaciones de “También te puede interesar” se aprenden de productos comprados juntos en pedidos pagados.</div></section></div><aside class="p-order-summary"><div class="p-section-title"><h2>Vista del catálogo</h2><Icon name="eye" :size="17"/></div><img v-if="form.images[0]" :src="form.images[0]" alt="Portada del producto" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:8px;margin-bottom:16px"/><div v-else class="p-whatsapp-preview" style="margin-bottom:18px;background:var(--surface-alt);border-color:var(--line)"><Icon name="image" :size="38"/></div><h3>{{form.name||'Nombre de tu producto'}}</h3><del v-if="form.previousPrice>form.price" class="p-muted">{{money(form.previousPrice)}}</del><strong style="display:block;font-size:22px;color:var(--text)">{{money(form.price)}}</strong><p class="p-help">{{form.type==='digital'?'Entrega digital por correo':form.madeToOrder?'Realizado a pedido':'Producto físico'}}</p><hr class="p-separator"/><label class="p-check"><input v-model="form.active" type="checkbox"/>Visible en la tienda</label><p class="p-help">Podés guardar un producto oculto y publicarlo cuando esté listo.</p><hr class="p-separator"/><label class="p-check"><input v-model="form.featured" type="checkbox"/>Destacar este producto</label><p class="p-help">Aparece en la sección Destacados cuando el producto y esa sección estén visibles.</p><span v-if="form.featured" class="product-featured-preview"><Icon name="star" :size="14"/>Destacado</span></aside></div><footer class="p-form-footer p-sticky-actions"><small>{{form.images.length}} fotos · {{form.variants.length}} variantes</small><div class="p-form-actions"><RouterLink to="/app/products" class="btn btn-secondary">Cancelar</RouterLink><button class="btn btn-primary" :disabled="saving||uploading||!workspace.activeStoreId">{{saving?'Guardando...':editing?'Guardar cambios':'Crear producto'}}</button></div></footer></form></div></template>

<style scoped>
.product-featured-preview{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border:1px solid var(--line);border-radius:20px;color:var(--primary);background:var(--surface-alt);font-size:11px}
</style>
